import React, { useState } from "react";
import { useSelector, useDispatch } from "react-redux";
import { useNavigate } from "react-router-dom";
import { logout } from "../features/auth/authSlice"; // ← Change this line

const UserMenu = () => {
  const [dropdownOpen, setDropdownOpen] = useState(false);

  const { user } = useSelector((state) => state.auth); // token not needed here

  const dispatch = useDispatch();
  const navigate = useNavigate();

  const handleLogout = () => {
    dispatch(logout()); // ← Use logout instead of clearCredentials

    // Optional: also clear refresh_token if you store it
    localStorage.removeItem("refresh_token");

    navigate("/login");
  };

  if (!user) return null;

  return (
    <div style={{ position: "relative", display: "inline-block" }}>
      {/* User Avatar + Email */}
      <div
        onClick={() => setDropdownOpen(!dropdownOpen)}
        style={{
          display: "flex",
          alignItems: "center",
          gap: "10px",
          cursor: "pointer",
          padding: "8px 16px",
          borderRadius: "8px",
          backgroundColor: dropdownOpen ? "#f0f0f0" : "transparent",
          transition: "background 0.2s",
        }}
      >
        {/* Simple User Icon (you can replace with an image or library like react-icons) */}
        <div
          style={{
            width: "40px",
            height: "40px",
            borderRadius: "50%",
            backgroundColor: "#667eea",
            color: "white",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            fontWeight: "bold",
            fontSize: "18px",
          }}
        >
          {user.email.charAt(0).toUpperCase()}
        </div>
        <span style={{ color: "#333", fontWeight: "500" }}>
          {user.email}
        </span>
      </div>

      {/* Dropdown Menu */}
      {dropdownOpen && (
        <>
          {/* Overlay to close dropdown when clicking outside */}
          <div
            style={{
              position: "fixed",
              top: 0,
              left: 0,
              right: 0,
              bottom: 0,
              zIndex: 9,
            }}
            onClick={() => setDropdownOpen(false)}
          />
          <div
            style={{
              position: "absolute",
              right: 0,
              top: "100%",
              marginTop: "8px",
              backgroundColor: "white",
              borderRadius: "8px",
              boxShadow: "0 4px 20px rgba(0,0,0,0.15)",
              minWidth: "200px",
              zIndex: 10,
              overflow: "hidden",
            }}
          >
            <div
              style={{
                padding: "12px 16px",
                borderBottom: "1px solid #eee",
                fontWeight: "500",
                color: "#333",
              }}
            >
              {user.email}
            </div>
            <button
              onClick={handleLogout}
              style={{
                width: "100%",
                padding: "12px 16px",
                textAlign: "left",
                background: "none",
                border: "none",
                cursor: "pointer",
                color: "#e74c3c",
                fontWeight: "500",
              }}
              onMouseOver={(e) => (e.target.style.backgroundColor = "#fdf2f2")}
              onMouseOut={(e) => (e.target.style.backgroundColor = "transparent")}
            >
              Logout
            </button>
          </div>
        </>
      )}
    </div>
  );
};

export default UserMenu;
